"""Backend of the Post-processing generator page (generators/postProcessGenerator.html).

The page works on maps that already exist in the scene -- the selected maps,
or else the last generated one (tp3d.currentMap). Jigsaw and sliding puzzle
pieces never count. Every tool the sidebar's Post-Process section offers
(Color by Height, Contour Lines, Magnet Holes, Dovetails, Bottom Mark,
Text / SVG import, 2D Heightmap) can be applied from the page; each Apply
changes the real objects right away and re-sends the scene as GLB for the
page's 3D viewer.

Undo is our own (PostProcessSession._undo_stack), not Blender's: before an
action, every object the page shows is copied (object + mesh data + paint
texture pixels); undoing swaps the copies back in with ID.user_remap, so
anything pointing at the objects (tp3d.currentMap, a contour piece's PARENT,
...) follows along.

Everything here runs on Blender's main thread, from
operators.TP3D_OT_post_process_generator.modal().
"""

import inspect
import json
import math
import struct

import bpy  # type: ignore
import numpy as np
from bpy.app.translations import pgettext_rpt as _rpt
from mathutils import Vector  # type: ignore

from . import constants as const
from . import temp

# Steps kept for the page's Undo button. Each holds a full copy of every
# object on the page, so this is a memory bound as much as a UI one.
MAX_UNDO_STEPS = 5

# Shapes dovetail_cutout knows how to cut.
DOVETAIL_SHAPES = {"SQUARE", "HEXAGON", "OCTAGON"}

# Text / SVG / heightmap operation choices (utils.projection's names).
PROJECTION_OPERATIONS = {"paint", "singleColorMode_remesh", "negative"}

_FALLBACK_SRGB = (200, 200, 200)

# The page's Export button: 3MF (colored models, needs the 3MF add-on), or
# STL / OBJ (one color).
EXPORT_FORMATS = ("3mf", "stl", "obj")


# ── Which maps the page works on ─────────────────────────────────────────


def is_page_map(obj, puzzle=False) -> bool:
    """A generated map the page can work on: no puzzle pieces (jigsaw and
    sliding both stamp PuzzleRow) and no Color by Height pieces. With
    *puzzle*, only puzzle pieces -- the page's puzzle mode, opened by the
    puzzle generators' hand-off."""
    try:
        return (
            obj is not None
            and obj.type == "MESH"
            and obj.get("Object type") == "MAP"
            and ("PuzzleRow" in obj) == bool(puzzle)
            and not obj.get("IsMountainPiece")
        )
    except ReferenceError:  # a removed object still held by a PointerProperty
        return False


def _in_scene(scene, obj) -> bool:
    try:
        return obj is not None and scene.objects.get(obj.name) is obj
    except ReferenceError:
        return False


def find_page_maps(context, puzzle=False) -> list:
    """The selected maps, or else the last generated one -- [] if neither.
    With *puzzle*: the selected puzzle pieces, nothing else.

    The last generated map is tp3d.currentMap; if that pointer is empty (or
    points at something gone), the newest map still in the scene: the only
    one, or the one most recently made current (props.LAST_MAP_STAMP_PROP)."""
    from .props import LAST_MAP_STAMP_PROP

    selected = [o for o in context.selected_objects if is_page_map(o, puzzle)]
    if selected or puzzle:
        return sorted(selected, key=lambda o: o.name)
    scene = context.scene
    current = scene.tp3d.currentMap
    if _in_scene(scene, current):
        # The last generation still exists: it's the target, or nothing is
        # (a puzzle as last generation doesn't fall back to an older map).
        return [current] if is_page_map(current) else []
    candidates = [o for o in scene.objects if is_page_map(o)]
    if len(candidates) == 1:
        return candidates
    stamped = [o for o in candidates if LAST_MAP_STAMP_PROP in o]
    if stamped:
        return [max(stamped, key=lambda o: float(o[LAST_MAP_STAMP_PROP]))]
    return []


def _world_bounds(obj):
    corners = [obj.matrix_world @ Vector(c) for c in obj.bound_box]
    return (
        min(c.x for c in corners), min(c.y for c in corners), min(c.z for c in corners),
        max(c.x for c in corners), max(c.y for c in corners), max(c.z for c in corners),
    )


def _is_addon_object(obj) -> bool:
    return "Object type" in obj or "objType" in obj or "Addon" in obj


def find_companions(context, maps) -> list:
    """Objects that belong with *maps* on the page: the addon-made parts
    whose footprint centre lies on one of the maps (trail, elements, text,
    plate/shell, Color by Height pieces, contour pieces) -- found by position
    so any element kind is covered. Never another puzzle piece."""
    names = {m.name for m in maps}
    boxes = [_world_bounds(m) for m in maps]
    # Multi Tile map connectors lie in a block beside the tiles, not on one
    # -- they belong by the batch's MultitileIndex (premium
    # operators_pe._place_map_connectors tags them with it).
    batch = {m["MultitileIndex"] for m in maps if "MultitileIndex" in m}
    view_layer = context.view_layer
    result = []
    for obj in context.scene.objects:
        if obj.name in names or obj.type not in {"MESH", "CURVE", "FONT"}:
            continue
        if not _is_addon_object(obj) or "PuzzleRow" in obj:
            continue
        try:
            if not obj.visible_get(view_layer=view_layer):
                continue
        except RuntimeError:
            continue
        parent = obj.get("PARENT")
        if parent is not None and getattr(parent, "name", None) in names:
            result.append(obj)
            continue
        if obj.get("Object type") == "CONNECTOR" and obj.get("MultitileIndex") in batch:
            result.append(obj)
            continue
        minx, miny, _minz, maxx, maxy, _maxz = _world_bounds(obj)
        cx, cy = (minx + maxx) / 2, (miny + maxy) / 2
        for bminx, bminy, _bz0, bmaxx, bmaxy, _bz1 in boxes:
            if bminx - 1.0 <= cx <= bmaxx + 1.0 and bminy - 1.0 <= cy <= bmaxy + 1.0:
                result.append(obj)
                break
    return result


def tile_of(obj, maps):
    """Name of the map in *maps* that *obj*'s footprint centre lies on
    (its PARENT first), or None."""
    parent = obj.get("PARENT")
    names = {m.name for m in maps}
    if parent is not None and getattr(parent, "name", None) in names:
        return parent.name
    minx, miny, _minz, maxx, maxy, _maxz = _world_bounds(obj)
    cx, cy = (minx + maxx) / 2, (miny + maxy) / 2
    for m in maps:
        bminx, bminy, _bz0, bmaxx, bmaxy, _bz1 = _world_bounds(m)
        if bminx - 1.0 <= cx <= bmaxx + 1.0 and bminy - 1.0 <= cy <= bmaxy + 1.0:
            return m.name
    return None


def base_object(map_obj, companions):
    """The part of *map_obj* that sits on the table: its plate or shell
    (Shape Extras) when it has one, else the map itself. Magnet holes and
    dovetails go into this one, like the sidebar does for a selected plate."""
    bminx, bminy, _z0, bmaxx, bmaxy, _z1 = _world_bounds(map_obj)
    for obj in companions:
        if obj.type != "MESH" or obj.get("Object type") not in {"PLATE", "SHELL"}:
            continue
        minx, miny, _a, maxx, maxy, _b = _world_bounds(obj)
        cx, cy = (minx + maxx) / 2, (miny + maxy) / 2
        if bminx - 1.0 <= cx <= bmaxx + 1.0 and bminy - 1.0 <= cy <= bmaxy + 1.0:
            return obj
    return map_obj


# ── Running the sidebar operators' own code ──────────────────────────────


class OperatorProxy:
    """Stands in for an operator instance so a sidebar operator's execute()
    (or helper method) can run as-is while its self.report() messages are
    collected for the page instead of going to Blender's status bar.

    Operator properties are passed as keyword arguments; everything else
    (methods, class constants) is looked up on the operator class."""

    def __init__(self, op_class, **props):
        self._op_class = op_class
        self.reports = []
        self.__dict__.update(props)

    def report(self, level, message):
        self.reports.append({"level": next(iter(level), "INFO"), "text": str(message)})

    def __getattr__(self, name):
        try:
            attr = inspect.getattr_static(self._op_class, name)
        except AttributeError:
            raise AttributeError(name) from None
        if isinstance(attr, staticmethod):
            return attr.__func__
        if isinstance(attr, classmethod):
            return attr.__func__.__get__(self._op_class)
        if inspect.isfunction(attr):
            return attr.__get__(self)
        return getattr(self._op_class, name)


def _select_only(context, objs, active=None):
    for obj in context.selected_objects:
        obj.select_set(False)
    for obj in objs:
        obj.select_set(True)
    context.view_layer.objects.active = active or (objs[0] if objs else None)


def _ensure_object_mode(context):
    if context.mode != "OBJECT" and context.view_layer.objects.active is not None:
        bpy.ops.object.mode_set(mode="OBJECT")


# ── Undo snapshots ───────────────────────────────────────────────────────


def _paint_image(obj):
    # Also a puzzle piece's, which shares the texture of the map it was cut from.
    from .utils.texture import find_paint_image

    return find_paint_image(obj)


def _save_image(image):
    from .utils import texture

    pixels = np.empty(len(image.pixels), dtype=np.float32)
    image.pixels.foreach_get(pixels)
    arr = pixels.reshape((image.size[1], image.size[0], 4))
    encoded = texture._encode_indexed(arr)
    if encoded is not None:
        return {"name": image.name, "indexed": encoded}
    return {"name": image.name, "raw": pixels}


def _restore_image(state):
    from .utils import texture

    image = bpy.data.images.get(state["name"])
    if image is None:
        return
    if "indexed" in state:
        palette, index, shape = state["indexed"]
        pixels = texture._decode_indexed(palette, index, shape).ravel()
    else:
        pixels = state["raw"]
    if len(pixels) != len(image.pixels):
        return  # the image was rebuilt at another size since
    image.pixels.foreach_set(pixels)
    image.pack()


def _remove_object(obj):
    data = obj.data
    bpy.data.objects.remove(obj, do_unlink=True)
    if data is not None and data.users == 0:
        if isinstance(data, bpy.types.Mesh):
            bpy.data.meshes.remove(data)
        elif isinstance(data, bpy.types.Curve):
            bpy.data.curves.remove(data)


class Snapshot:
    """Everything needed to put *objects* back the way they are now."""

    def __init__(self, label, scene, objects):
        self.label = label
        # pointer -> name of every object in the scene before the action.
        self.before = {o.as_pointer(): o.name for o in scene.objects}
        # pointer -> name of the objects the action created (mark_done) --
        # removed on undo. Only those: an object the user adds in Blender
        # while the page is open must survive the page's Undo.
        self.created = None
        self.entries = []
        # Each texture once: puzzle pieces all share their map's.
        saved_images = set()
        for obj in objects:
            copy = obj.copy()
            if obj.data is not None:
                copy.data = obj.data.copy()
            image = _paint_image(obj)
            if image is not None and image.name in saved_images:
                image = None
            elif image is not None:
                saved_images.add(image.name)
            self.entries.append({
                "name": obj.name,
                "data_name": obj.data.name if obj.data is not None else None,
                "copy": copy,
                "collections": [c.name for c in obj.users_collection],
                "image": _save_image(image) if image is not None else None,
            })

    def mark_done(self, scene):
        """Record what the action created -- call right after it ran."""
        self.created = {
            o.as_pointer(): o.name
            for o in scene.objects
            if self.before.get(o.as_pointer()) != o.name
        }

    def valid(self) -> bool:
        """False once Blender's own undo (or a file reload) has replaced the
        data these copies point into."""
        try:
            for entry in self.entries:
                entry["copy"].name  # noqa: B018 - raises ReferenceError when stale
        except ReferenceError:
            return False
        return True

    def restore(self, scene):
        for obj in list(scene.objects):
            ptr = obj.as_pointer()
            if self.created is None:  # mid-action failure: everything new goes
                new = self.before.get(ptr) != obj.name
            else:
                new = self.created.get(ptr) == obj.name
            if new:
                _remove_object(obj)
        for entry in self.entries:
            copy = entry["copy"]
            current = scene.objects.get(entry["name"])
            if current is not None:
                old_data = current.data
                # Every user of the current object -- its collections,
                # tp3d.currentMap, other objects' PARENT -- now uses the copy.
                current.user_remap(copy)
                bpy.data.objects.remove(current, do_unlink=True)
                if old_data is not None and old_data.users == 0:
                    if isinstance(old_data, bpy.types.Mesh):
                        bpy.data.meshes.remove(old_data)
                    elif isinstance(old_data, bpy.types.Curve):
                        bpy.data.curves.remove(old_data)
            if not copy.users_collection:
                targets = [bpy.data.collections.get(n) for n in entry["collections"]]
                targets = [c for c in targets if c is not None] or [scene.collection]
                for coll in targets:
                    coll.objects.link(copy)
            copy.name = entry["name"]
            if copy.data is not None and entry["data_name"]:
                copy.data.name = entry["data_name"]
            if entry["image"] is not None:
                _restore_image(entry["image"])
        self.entries = []

    def discard(self):
        for entry in self.entries:
            copy = entry["copy"]
            try:
                if copy.users_collection:
                    continue  # restored into the scene; not ours any more
                _remove_object(copy)
            except ReferenceError:
                pass
        self.entries = []


# ── GLB for the page's viewer ────────────────────────────────────────────


def _srgb_to_linear(c):
    c = np.asarray(c, dtype=np.float32)
    return np.where(c <= 0.04045, c / 12.92, ((c + 0.055) / 1.055) ** 2.4)


def _material_info(material, image_cache):
    """('texture', pixels HxWx4 sRGB) or ('color', linear rgb) for one slot."""
    from .utils.color import material_to_srgb

    if material is not None and material.use_nodes and material.node_tree is not None:
        bsdf = next((n for n in material.node_tree.nodes if n.type == "BSDF_PRINCIPLED"), None)
        if bsdf is not None:
            base = bsdf.inputs.get("Base Color")
            if base is not None and base.is_linked:
                node = base.links[0].from_node
                if node.type == "TEX_IMAGE" and node.image is not None and node.image.size[0] > 0:
                    image = node.image
                    if image.name not in image_cache:
                        px = np.empty(len(image.pixels), dtype=np.float32)
                        image.pixels.foreach_get(px)
                        image_cache[image.name] = px.reshape((image.size[1], image.size[0], 4))
                    return ("texture", image_cache[image.name])
    srgb = material_to_srgb(material, _FALLBACK_SRGB) if material is not None else _FALLBACK_SRGB
    return ("color", _srgb_to_linear(np.array(srgb, dtype=np.float32) / 255.0))


def _object_triangles(obj, depsgraph, image_cache):
    """(positions (N*3, 3) float32 world mm, colors (N*3, 3) linear) or None."""
    evaluated = obj.evaluated_get(depsgraph)
    try:
        mesh = evaluated.to_mesh()
    except RuntimeError:
        return None
    try:
        mesh.calc_loop_triangles()
        n = len(mesh.loop_triangles)
        if n == 0:
            return None
        tri_verts = np.empty(n * 3, dtype=np.int32)
        mesh.loop_triangles.foreach_get("vertices", tri_verts)
        tri_loops = np.empty(n * 3, dtype=np.int32)
        mesh.loop_triangles.foreach_get("loops", tri_loops)
        tri_mats = np.empty(n, dtype=np.int32)
        mesh.loop_triangles.foreach_get("material_index", tri_mats)
        co = np.empty(len(mesh.vertices) * 3, dtype=np.float32)
        mesh.vertices.foreach_get("co", co)
        co = co.reshape(-1, 3).astype(np.float64)
        mw = np.array(obj.matrix_world, dtype=np.float64)
        world = co @ mw[:3, :3].T + mw[:3, 3]
        positions = world[tri_verts].astype(np.float32)

        slots = [s.material for s in evaluated.material_slots] or [None]
        colors = np.empty((n * 3, 3), dtype=np.float32)
        uv = None
        corner_mats = np.repeat(tri_mats, 3)
        for index in np.unique(tri_mats):
            material = slots[index] if 0 <= index < len(slots) else None
            kind, value = _material_info(material, image_cache)
            mask = corner_mats == index
            if kind == "texture":
                if uv is None:
                    layer = mesh.uv_layers.active
                    if layer is None:
                        colors[mask] = _srgb_to_linear(np.array(_FALLBACK_SRGB) / 255.0)
                        continue
                    uv = np.empty(len(mesh.loops) * 2, dtype=np.float32)
                    layer.data.foreach_get("uv", uv)
                    uv = uv.reshape(-1, 2)
                h, w = value.shape[:2]
                corner_uv = uv[tri_loops[mask]]
                px = np.clip((corner_uv[:, 0] * w).astype(np.int64), 0, w - 1)
                py = np.clip((corner_uv[:, 1] * h).astype(np.int64), 0, h - 1)
                colors[mask] = _srgb_to_linear(value[py, px, :3])
            else:
                colors[mask] = value
        return positions, colors
    finally:
        evaluated.to_mesh_clear()


def write_scene_glb(path, parts, depsgraph):
    """Write [(obj, extras), ...] as binary glTF: one non-indexed, flat
    triangle primitive per object with per-corner COLOR_0 (linear, ushort),
    in Blender world coordinates (Z-up, mm). No normals -- the page shades
    flat. *extras* ends up as the three.js object's userData."""
    image_cache = {}
    chunks, buffer_views, accessors, meshes, nodes = [], [], [], [], []
    offset = 0

    def add_view(data):
        nonlocal offset
        pad = (-len(data)) % 4
        chunks.append(data + b"\x00" * pad)
        buffer_views.append({"buffer": 0, "byteOffset": offset, "byteLength": len(data), "target": 34962})
        offset += len(data) + pad
        return len(buffer_views) - 1

    total_tris = 0
    for obj, extras in parts:
        tris = _object_triangles(obj, depsgraph, image_cache)
        if tris is None:
            continue
        positions, colors = tris
        total_tris += len(positions) // 3
        rgba = np.ones((len(colors), 4), dtype=np.float32)
        rgba[:, :3] = np.clip(colors, 0.0, 1.0)
        color_u16 = np.round(rgba * 65535).astype("<u2")
        pos_view = add_view(positions.astype("<f4").tobytes())
        col_view = add_view(color_u16.tobytes())
        accessors.append({
            "bufferView": pos_view, "componentType": 5126, "count": len(positions), "type": "VEC3",
            "min": positions.min(axis=0).tolist(), "max": positions.max(axis=0).tolist(),
        })
        accessors.append({
            "bufferView": col_view, "componentType": 5123, "normalized": True,
            "count": len(positions), "type": "VEC4",
        })
        meshes.append({"name": obj.name, "primitives": [{
            "attributes": {"POSITION": len(accessors) - 2, "COLOR_0": len(accessors) - 1},
        }]})
        nodes.append({"name": obj.name, "mesh": len(meshes) - 1, "extras": extras})

    binary = b"".join(chunks)
    gltf = {
        "asset": {"version": "2.0", "generator": "TrailPrint3D"},
        "scene": 0,
        "scenes": [{"nodes": list(range(len(nodes)))}],
        "nodes": nodes,
        "meshes": meshes,
        "accessors": accessors,
        "bufferViews": buffer_views,
        "buffers": [{"byteLength": len(binary)}],
    }
    if not nodes:
        del gltf["accessors"], gltf["bufferViews"], gltf["buffers"], gltf["meshes"]
    json_bytes = json.dumps(gltf, separators=(",", ":")).encode("utf-8")
    json_bytes += b" " * ((-len(json_bytes)) % 4)
    total = 12 + 8 + len(json_bytes) + (8 + len(binary) if nodes else 0)
    with open(path, "wb") as f:
        f.write(struct.pack("<III", 0x46546C67, 2, total))
        f.write(struct.pack("<II", len(json_bytes), 0x4E4F534A))
        f.write(json_bytes)
        if nodes:
            f.write(struct.pack("<II", len(binary), 0x004E4942))
            f.write(binary)
    return total_tris


# ── Per-map info for the page ────────────────────────────────────────────


def _dovetail_spots(obj):
    """[{index, angle, x, y}] -- world XY of each dovetail-able edge's middle,
    in dovetail_side_angles' order (what dovetail_cutout's *sides* index)."""
    from .operators import dovetail_side_angles
    from .utils import geometry2d as g2d
    from .utils.outline import get_bottom_outline

    outline = get_bottom_outline(obj)
    if outline is None:
        return []
    polys = list(g2d.iter_polygons(outline))
    if not polys:
        return []
    poly = max(polys, key=lambda p: p.area)
    c = poly.centroid
    minx, miny, maxx, maxy = poly.bounds
    reach = (maxx - minx + maxy - miny) * 2
    spots = []
    mw = obj.matrix_world
    for index, angle in enumerate(dovetail_side_angles(obj)):
        ray = g2d.LineString([(c.x, c.y), (c.x + math.cos(angle) * reach, c.y + math.sin(angle) * reach)])
        hit = ray.intersection(poly.exterior)
        points = [g for g in getattr(hit, "geoms", [hit]) if not g.is_empty and hasattr(g, "x")]
        if not points:
            continue
        far = max(points, key=lambda p: (p.x - c.x) ** 2 + (p.y - c.y) ** 2)
        world = mw @ Vector((far.x, far.y, 0.0))
        spots.append({"index": index, "angle": angle, "x": world.x, "y": world.y})
    return spots


def _mm_per_meter(obj):
    from .utils.terrain import get_effective_cl_values

    distance, _offset, _valid = get_effective_cl_values(obj, 1.0, 0.0, 0.0, True)
    return distance


def map_info(context, map_obj, companions, index):
    from . import operators

    tp3d = context.scene.tp3d
    base = base_object(map_obj, companions)
    minx, miny, minz, maxx, maxy, maxz = _world_bounds(map_obj)
    bminz = _world_bounds(base)[2]
    shape = base.get("Shape") or map_obj.get("Shape")
    dovetail_reason = None
    if base.get("Dovetail"):
        dovetail_reason = _rpt("Already has dovetail cutouts")
    elif shape not in DOVETAIL_SHAPES:
        dovetail_reason = _rpt("Dovetails need a Square, Hexagon, or Octagon shape")
    height_range = operators._color_height_range(map_obj)
    offset = map_obj.matrix_world.translation.z
    sem = operators._mountain_split_ineligible_reason(map_obj, tp3d, mode=operators.SPLIT_SINGLE_EXTRUDER)
    mem = operators._mountain_split_ineligible_reason(map_obj, tp3d, mode=operators.SPLIT_MULTI_EXTRUDER)
    try:
        mm_per_meter = _mm_per_meter(map_obj)
    except (KeyError, TypeError, ValueError, ZeroDivisionError):
        mm_per_meter = None
    return {
        "name": map_obj.name,
        "index": index,
        "shape": shape,
        "bounds": [minx, miny, minz, maxx, maxy, maxz],
        "bottomZ": min(minz, bminz),
        "originZ": offset,
        # The page's Color by Height noise preview works in the map's local
        # X/Y, like the texture bake (utils/texture._value_noise_field).
        "originX": map_obj.matrix_world.translation.x,
        "originY": map_obj.matrix_world.translation.y,
        "base": base.name,
        "colorRange": [height_range[0] + offset, height_range[1] + offset] if height_range else None,
        "splitReasonSEM": sem,
        "splitReasonMEM": mem,
        "textured": operators._paint_texture_state(map_obj.data) == "texture",
        # Every Color by Height path (paint, texture, Single/Multi Extruder)
        # records its last cut on the map.
        "colorHeight": map_obj.get("lastMountianCut") is not None,
        # Contour Lines leaves a "<map>_LINES" part whose PARENT is the map.
        "contourLines": any(
            o.get("Object type") == "LINES" and o.get("PARENT") == map_obj
            for o in context.scene.objects
        ),
        "mmPerMeter": mm_per_meter,
        "magnetHoles": bool(base.get("MagnetHoles")),
        "dovetail": bool(base.get("Dovetail")),
        "dovetailReason": dovetail_reason,
        "dovetailSpots": [] if dovetail_reason else _dovetail_spots(base),
        "bottomMark": None if "BottomMark" not in map_obj else bool(map_obj["BottomMark"]),
    }


def default_export_name(context, maps) -> str:
    """The scene's Model Name (what the sidebar's 3MF export suggests), else
    the first map's name."""
    return (context.scene.tp3d.modelname or "").strip() or maps[0].name


def is_multicolor(objects) -> bool:
    """Whether *objects* print in more than one color: a paint-textured
    part, or more than one distinct color among the materials their faces
    actually use (one per part for curves/text)."""
    from .utils.color import material_to_srgb

    colors = set()
    for obj in objects:
        data = getattr(obj, "data", None)
        if data is None:
            continue
        if obj.type == "MESH" and data.get("3mf_is_paint_texture") and _paint_image(obj) is not None:
            return True
        materials = list(getattr(data, "materials", []))
        used = materials[:1]
        if obj.type == "MESH" and len(materials) > 1 and len(data.polygons):
            index = np.empty(len(data.polygons), dtype=np.int32)
            data.polygons.foreach_get("material_index", index)
            used = [materials[i] for i in np.unique(index) if i < len(materials)]
        if not used:
            used = [None]
        for material in used:
            colors.add(tuple(material_to_srgb(material)) if material is not None else None)
        if len(colors) > 1:
            return True
    return False


# ── Session ──────────────────────────────────────────────────────────────


class PostProcessSession:
    """One open Post-processing page: the maps it works on, its undo stack
    and the requests it gets from the page."""

    # Puzzle mode: only these -- the rest (Color by Height, magnets,
    # dovetails...) would break the pieces' fit or doesn't apply to them.
    # Text and SVG are painted only (see _placement); Bottom Mark marks
    # every piece.
    PUZZLE_ACTIONS = ("text", "svg", "bottom_mark")

    def __init__(self, map_names, puzzle=False):
        self.map_names = list(map_names)
        # Working on puzzle pieces (see is_page_map) -- Text and SVG only.
        self.puzzle = bool(puzzle)
        self._undo_stack = []

    # -- objects --------------------------------------------------------

    def maps(self, context):
        result = []
        for name in self.map_names:
            obj = context.scene.objects.get(name)
            if obj is not None and is_page_map(obj, self.puzzle):
                result.append(obj)
        return result

    def _map(self, context, name):
        maps = self.maps(context)
        for obj in maps:
            if obj.name == name:
                return obj
        return maps[0] if maps else None

    def page_objects(self, context):
        maps = self.maps(context)
        return maps, find_companions(context, maps)

    def enabled_objects(self, context, disabled):
        """page_objects without the tiles switched off on the page
        (*disabled*: map names) -- what an Apply or preview works on."""
        maps = [m for m in self.maps(context) if m.name not in disabled]
        return maps, find_companions(context, maps)

    # -- requests -------------------------------------------------------

    def handle(self, context, request):
        """Run one page request. Returns the job result dict; 'rebuild'
        True means the scene changed and the GLB must be re-sent."""
        kind = request.get("kind")
        action = request.get("action")
        params = request.get("params") or {}
        # Tiles switched off on the page: Apply and previews leave them alone.
        disabled = {str(n) for n in (request.get("disabled") or [])}
        if kind == "info":
            return {"rebuild": True}
        if kind == "undo":
            return self.undo(context)
        if kind == "preview":
            return {"preview": self.preview(context, action, params, disabled)}
        if kind == "apply":
            return self.apply(context, action, params, disabled)
        if kind == "export":
            return self.export(context, params.get("format"), params.get("name", ""))
        return {"messages": [{"level": "ERROR", "text": f"Unknown request {kind!r}"}]}

    def info(self, context):
        maps, companions = self.page_objects(context)
        infos = [map_info(context, m, companions, i) for i, m in enumerate(maps)]
        ranges = [i["colorRange"] for i in infos if i["colorRange"]]
        return {
            "maps": infos,
            "colorRange": [min(r[0] for r in ranges), max(r[1] for r in ranges)] if ranges else None,
            "undo": [s.label for s in self._undo_stack],
            "premium": bool(temp.PREMIUMVERSION),
            "puzzle": self.puzzle,
            # Picks the page's Export choices: 3MF keeps colors, STL/OBJ don't.
            "colored": is_multicolor(maps + companions),
            "has3mf": bool(temp.has3mf),
            # What the page's export-name field starts with.
            "exportName": default_export_name(context, maps) if maps else "",
        }

    # -- export ---------------------------------------------------------

    def export(self, context, fmt, name=""):
        """Export everything the page shows (maps and their parts) into the
        export folder, the same way the sidebar's Export buttons do.

        *name* is the page's export name: the 3MF's file name. STL/OBJ write
        one file per part -- a single map gets *name* itself, every other
        part "<name>_<object name>"."""
        import os
        import time

        from . import addon_preferences
        from . import export as tp3d_export

        if fmt not in EXPORT_FORMATS:
            return {"messages": [{"level": "ERROR", "text": f"Unknown export format {fmt!r}"}]}
        maps, companions = self.page_objects(context)
        if not maps:
            return {"messages": [{"level": "ERROR", "text": _rpt("The map is no longer in the scene.")}]}
        folder = addon_preferences.get_export_folder(context.scene.tp3d)
        if not folder or not os.path.isdir(bpy.path.abspath(folder)):
            return {"messages": [{"level": "ERROR", "text": _rpt("Choose an export folder first.")}]}
        if fmt == "3mf" and not tp3d_export.is_3mf_extension_installed():
            return {"messages": [{"level": "ERROR", "text": _rpt("3MF extension is not installed.")}]}

        _ensure_object_mode(context)
        objects = maps + companions
        _select_only(context, objects, active=maps[0])
        name = str(name or "").strip() or default_export_name(context, maps)
        started = time.time()
        try:
            if fmt == "3mf":
                tp3d_export.export_selected_to_3mf(name, manual=True)
                names = [name]
            else:
                file_names = {o.name: f"{name}_{o.name}" for o in objects}
                if len(maps) == 1:
                    file_names[maps[0].name] = name
                tp3d_export.export_selected_to_STL(fmt.upper(), file_names=file_names)
                names = [file_names[o.name] for o in objects]
        finally:
            _select_only(context, self.maps(context))

        # The export helpers report into Blender's overlay only -- check the
        # files themselves for the page.
        paths = [bpy.path.abspath(folder + tp3d_export._sanitize_filename(n) + "." + fmt) for n in names]
        written = [p for p in paths if os.path.isfile(p) and os.path.getmtime(p) >= started - 2]
        label = fmt.upper()
        if not written:
            return {"messages": [{"level": "ERROR", "text": _rpt(
                "{fmt} export failed. Check Blender's System Console.").format(fmt=label)}]}
        if len(written) == 1:
            text = _rpt("Exported {file}").format(file=os.path.basename(written[0]))
        else:
            text = _rpt("Exported {count} {fmt} files").format(count=len(written), fmt=label)
        messages = [{"level": "INFO", "text": text + "\n" + os.path.dirname(written[0])}]
        if len(written) < len(paths):
            messages.append({"level": "WARNING", "text": _rpt(
                "{count} part(s) were not exported.").format(count=len(paths) - len(written))})
        return {"messages": messages}

    def write_glb(self, context, path):
        maps, companions = self.page_objects(context)
        map_names = {m.name for m in maps}
        parts = []
        for obj in maps + companions:
            owner = obj.name if obj.name in map_names else None
            parts.append((obj, {
                "name": obj.name,
                "role": "map" if owner else str(obj.get("Object type") or "part").lower(),
                "map": owner,
                # The tile it sits on -- the page greys a switched-off tile's parts too.
                "tile": owner or tile_of(obj, maps),
            }))
        return write_scene_glb(path, parts, context.evaluated_depsgraph_get())

    # -- undo -----------------------------------------------------------

    def _push(self, snapshot):
        self._undo_stack.append(snapshot)
        while len(self._undo_stack) > MAX_UNDO_STEPS:
            self._undo_stack.pop(0).discard()

    def undo(self, context):
        if not self._undo_stack:
            return {"messages": [{"level": "INFO", "text": _rpt("Nothing to undo.")}]}
        snapshot = self._undo_stack.pop()
        if not snapshot.valid():
            self.clear_undo()
            return {"rebuild": True, "messages": [{"level": "WARNING", "text": _rpt(
                "Undo history was reset because the scene was changed in Blender (Ctrl+Z or a file reload).")}]}
        _ensure_object_mode(context)
        snapshot.restore(context.scene)
        _select_only(context, self.maps(context))
        bpy.ops.ed.undo_push(message="Post-processing: Undo")
        return {"rebuild": True, "messages": [{"level": "INFO", "text": _rpt("Undid: {label}").format(label=snapshot.label)}]}

    def clear_undo(self):
        for snapshot in self._undo_stack:
            snapshot.discard()
        self._undo_stack = []

    def dispose(self):
        self.clear_undo()

    # -- apply ----------------------------------------------------------

    _LABELS = {
        "color_height": "Color by Height",
        "contour_lines": "Contour Lines",
        "magnets": "Magnet Holes",
        "dovetails": "Dovetails",
        "bottom_mark": "Bottom Mark",
        "text": "Text",
        "svg": "SVG",
        "heightmap": "2D Heightmap",
    }

    def apply(self, context, action, params, disabled=()):
        handler = getattr(self, f"_apply_{action}", None)
        if handler is None or action not in self._LABELS:
            return {"messages": [{"level": "ERROR", "text": f"Unknown action {action!r}"}]}
        if self.puzzle and action not in self.PUZZLE_ACTIONS:
            return {"messages": [{"level": "ERROR", "text": _rpt(
                "{action} isn't available for puzzles.").format(action=self._LABELS[action])}]}
        if not self.maps(context):
            return {"messages": [{"level": "ERROR", "text": _rpt("The map is no longer in the scene.")}]}
        maps, companions = self.enabled_objects(context, disabled)
        if not maps:
            return {"messages": [{"level": "WARNING", "text": _rpt(
                "Every tile is switched off. Click a tile in the 3D view to switch it back on.")}]}
        _ensure_object_mode(context)
        snapshot = Snapshot(self._LABELS[action], context.scene, maps + companions)
        cursor = context.scene.cursor.location.copy()
        messages = []
        try:
            changed = handler(context, maps, companions, params, messages)
        except Exception as exc:  # noqa: BLE001 - reported on the page, scene put back
            import traceback

            traceback.print_exc()
            _ensure_object_mode(context)
            snapshot.restore(context.scene)
            context.scene.cursor.location = cursor
            _select_only(context, self.maps(context))
            messages.append({"level": "ERROR", "text": _rpt("{action} failed: {error}").format(
                action=self._LABELS[action], error=exc)})
            return {"rebuild": True, "messages": messages}
        context.scene.cursor.location = cursor
        _ensure_object_mode(context)
        _select_only(context, self.maps(context))
        if not changed:
            # Put back whatever a partly failed action did touch, so an
            # action is either applied as a whole (and undoable) or not at all.
            snapshot.restore(context.scene)
            _select_only(context, self.maps(context))
            if not any(m["level"] in {"ERROR", "WARNING"} for m in messages):
                messages.append({"level": "WARNING", "text": _rpt("Nothing was changed.")})
            return {"rebuild": True, "messages": messages}
        snapshot.mark_done(context.scene)
        # Parts an action leaves behind (a bottom-side text or heightmap
        # inlay, ...) often carry no addon metadata -- tag them so they stay
        # part of the page (viewer, later undo snapshots).
        for obj in context.scene.objects:
            if snapshot.created.get(obj.as_pointer()) == obj.name and not _is_addon_object(obj):
                obj["Addon"] = const.ADDON_NAME
        self._push(snapshot)
        bpy.ops.ed.undo_push(message=f"Post-processing: {self._LABELS[action]}")
        messages.insert(0, {"level": "INFO", "text": _rpt("{action} applied.").format(action=self._LABELS[action])})
        return {"rebuild": True, "messages": messages}

    @staticmethod
    def _run(proxy, func, context, messages, *args):
        result = func(context, *args)
        messages.extend(proxy.reports)
        proxy.reports = []
        return result

    def _apply_color_height(self, context, maps, companions, params, messages):
        from . import operators

        tp3d = context.scene.tp3d
        mode = params.get("mode", "paint")
        tp3d.toleranceElements = float(params.get("tolerance", tp3d.toleranceElements))
        tp3d.elementShellThickness = float(params.get("thickness", tp3d.elementShellThickness))
        bands = params.get("bands") or [{
            "threshold": params.get("threshold", tp3d.mountain_treshold),
            "color": params.get("color", tp3d.mountain_color),
        }]
        # Lowest band first: each band recolors everything above it, so a
        # higher band applied afterwards stacks on top instead of being
        # painted over.
        bands = sorted(bands, key=lambda b: float(b.get("threshold", 0)))
        from .utils.texture import reuse_height_field

        with reuse_height_field():
            return self._apply_color_bands(context, maps, params, messages, bands, mode)

    def _apply_color_bands(self, context, maps, params, messages, bands, mode):
        from . import operators

        tp3d = context.scene.tp3d
        split = mode in ("SEM", "MEM")
        targets = list(maps)
        applied = False
        for band in bands:
            if not targets:
                break
            proxy = OperatorProxy(
                operators.TP3D_OT_color_mountain,
                mountain_treshold=int(round(float(band.get("threshold", tp3d.mountain_treshold)))),
                mountain_color=tuple(float(c) for c in band.get("color", tp3d.mountain_color))[:3],
                color_height_SEM=mode == "SEM",
                color_height_MEM=mode == "MEM",
                mountain_noise=bool(params.get("noise", False)),
                mountain_noise_amplitude=float(params.get("noiseAmplitude", tp3d.mountain_noise_amplitude)),
                mountain_noise_scale=max(0.005, float(params.get("noiseScale", tp3d.mountain_noise_scale))),
            )
            pieces_before = {o.name for o in bpy.data.objects if o.get("IsMountainPiece")}
            _select_only(context, targets)
            result = self._run(proxy, proxy.execute, context, messages)
            if "FINISHED" not in result or any(m["level"] == "ERROR" for m in messages):
                return False
            applied = True
            if split:
                # Single / Multi Extruder stack the next color on the piece
                # this band just split off, like selecting it in the sidebar.
                targets = [o for o in bpy.data.objects
                           if o.get("IsMountainPiece") and o.name not in pieces_before]
        return applied

    def _apply_contour_lines(self, context, maps, companions, params, messages):
        from .utils.terrain import contourLines, get_effective_cl_values

        tp3d = context.scene.tp3d
        tp3d.cl_useRealMeters = bool(params.get("realMeters", tp3d.cl_useRealMeters))
        tp3d.cl_thickness = float(params.get("thickness", tp3d.cl_thickness))
        tp3d.cl_distance = float(params.get("distance", tp3d.cl_distance))
        tp3d.cl_offset = float(params.get("offset", tp3d.cl_offset))
        valid = []
        for obj in maps:
            _d, _o, ok = get_effective_cl_values(
                obj, tp3d.cl_distance, tp3d.cl_offset, tp3d.cl_thickness, tp3d.cl_useRealMeters
            )
            if ok:
                valid.append(obj)
            else:
                messages.append({"level": "WARNING", "text": _rpt(
                    "{name}: the line distance must be larger than the line thickness.").format(name=obj.name)})
        if not valid:
            return False
        _select_only(context, valid)
        result = contourLines(valid)
        return "FINISHED" in result

    def _apply_magnets(self, context, maps, companions, params, messages):
        from . import operators

        tp3d = context.scene.tp3d
        tp3d.magnetDiameter = float(params.get("diameter", tp3d.magnetDiameter))
        tp3d.magnetHeight = float(params.get("depth", tp3d.magnetHeight))
        tp3d.magnetMargin = float(params.get("margin", tp3d.magnetMargin))
        tp3d.magnetCount = int(params.get("count", tp3d.magnetCount))
        targets = [base_object(m, companions) for m in maps]
        proxy = OperatorProxy(operators.TP3D_OT_magnet_holes)
        _select_only(context, targets)
        result = self._run(proxy, proxy.execute, context, messages)
        return "FINISHED" in result

    def _apply_dovetails(self, context, maps, companions, params, messages):
        from .operators import dovetail_cutout

        sides_by_map = params.get("sides") or {}
        cut = 0
        for obj in maps:
            base = base_object(obj, companions)
            if base.get("Dovetail") or (base.get("Shape") or obj.get("Shape")) not in DOVETAIL_SHAPES:
                continue
            sides = {int(i) for i in sides_by_map.get(obj.name, [])}
            if not sides:
                continue
            _select_only(context, [base])
            if dovetail_cutout(base, sides=sides):
                cut += 1
            else:
                messages.append({"level": "WARNING", "text": _rpt(
                    "{name}: the dovetail cut failed.").format(name=base.name)})
        if not cut:
            messages.append({"level": "WARNING", "text": _rpt("No dovetail cutouts were added")})
        return cut > 0

    def _apply_bottom_mark(self, context, maps, companions, params, messages):
        from . import operators

        tp3d = context.scene.tp3d
        tp3d.bottomMarkCutout = bool(params.get("cutout", tp3d.bottomMarkCutout))
        targets = [
            o for o in maps
            if o.type == "MESH" and "objSize" in o and "BottomMark" in o and not o["BottomMark"]
        ]
        if not targets:
            messages.append({"level": "WARNING", "text": _rpt("Every map already has a bottom mark.")})
            return False
        proxy = OperatorProxy(operators.TP3D_OT_bottom_mark)
        for obj in targets:
            _select_only(context, [obj])
            self._run(proxy, proxy._mark_tile, context, messages, obj, tp3d.bottomMarkCutout)
            # The operator's own filter skips maps with BottomMark set, but
            # nothing sets it -- do it here so a second Apply can't mark twice.
            obj["BottomMark"] = True
        return True

    def _placement(self, params, map_obj):
        x = float(params.get("x", map_obj.location.x))
        y = float(params.get("y", map_obj.location.y))
        rotation = math.radians(float(params.get("rotation", 0.0)))
        # Puzzles: painted on top only -- a cut or raised part (or a
        # bottom-side shape, always cut in) would change the pieces' shape.
        bottom = bool(params.get("bottom", False)) and not self.puzzle
        operation = params.get("operation", "paint")
        if operation not in PROJECTION_OPERATIONS or self.puzzle:
            operation = "paint"
        color = tuple(float(c) for c in params.get("color", (1.0, 1.0, 1.0)))[:3]
        return x, y, rotation, bottom, operation, color if operation == "paint" else None

    def _apply_text(self, context, maps, companions, params, messages):
        from .operators import finish_text_placement
        from .utils.scene import getHighestLowest

        map_obj = self._map(context, params.get("map"))
        body = str(params.get("text") or "").strip()
        if not body:
            messages.append({"level": "WARNING", "text": _rpt("Enter some text first.")})
            return False
        x, y, rotation, bottom, operation, color = self._placement(params, map_obj)
        context.scene.cursor.location = map_obj.location.copy()
        obj = _build_text_object(context, body, params.get("font") or "", float(params.get("size", 10.0)))
        obj.location = (x, y, map_obj.location.z)
        obj.rotation_euler.z = rotation
        obj.scale.x = -1.0 if bottom else 1.0
        if params.get("font"):
            context.scene.tp3d.textFont = params["font"]

        # Onto every tile the text reaches, each with its own copy (the
        # placement consumes it and clips it to that tile).
        targets = maps_covered_by(context, obj, maps, map_obj)
        if not targets:
            messages.append(_off_tiles_only_message())
            return False
        pieces = [obj] + [_duplicate(obj) for _ in targets[1:]]
        for target, piece in zip(targets, pieces):
            context.scene.cursor.location = target.location.copy()
            low, high = getHighestLowest(target)
            piece.location.z = (low - 0.2) if bottom else (high + 0.2)
            error = finish_text_placement(context, target, piece, bottom, operation, color)
            if error:
                raise RuntimeError(error)
        return True

    def _apply_svg(self, context, maps, companions, params, messages):
        from .operators import finish_svg_placement
        from .utils.scene import getHighestLowest, importSVGtoMerge

        map_obj = self._map(context, params.get("map"))
        svg_path = params.get("svgPath") or ""
        if not svg_path:
            messages.append({"level": "WARNING", "text": _rpt("Choose an SVG file first.")})
            return False
        x, y, rotation, bottom, operation, color = self._placement(params, map_obj)
        scale = float(params.get("scale", 1.0))
        context.scene.cursor.location = map_obj.location.copy()
        _select_only(context, [map_obj])
        svg = importSVGtoMerge(map_obj, svg_path)
        if svg is None:
            raise RuntimeError(_rpt("The SVG file has no usable shapes."))
        svg.data.materials.clear()
        svg.location = (x, y, map_obj.location.z)
        svg.rotation_euler.z = rotation
        svg.scale.x = -scale if bottom else scale
        svg.scale.y = scale

        # Onto every tile the SVG reaches, each with its own copy (the
        # placement consumes it and clips it to that tile).
        targets = maps_covered_by(context, svg, maps, map_obj)
        if not targets:
            messages.append(_off_tiles_only_message())
            return False
        pieces = [svg] + [_duplicate(svg) for _ in targets[1:]]
        for target, piece in zip(targets, pieces):
            if "highestZ" in target and "minThickness" in target:
                top = target["highestZ"] + target["minThickness"] + 0.5 + target.location.z
                low = target.location.z - 0.5
            else:
                low, top = getHighestLowest(target)
                low, top = low - 0.2, top + 0.2
            piece.location.z = low if bottom else top
            context.scene.cursor.location = target.location.copy()
            error = finish_svg_placement(context, target, piece, bottom, operation, color)
            if error:
                # Fails the action -- the scene is put back, the page shows why.
                raise RuntimeError(error)
        return True

    def _apply_heightmap(self, context, maps, companions, params, messages):
        if not temp.PREMIUMVERSION:
            messages.append({"level": "ERROR", "text": _rpt("The 2D Heightmap is a Premium feature.")})
            return False
        from .premium import operators_pe  # type: ignore[import]
        from .utils.io_gpx import read_gpx_and_create_heightmap

        map_obj = self._map(context, params.get("map"))
        x, y, rotation, _bottom, _operation, _color = self._placement(params, map_obj)
        context.scene.cursor.location = map_obj.location.copy()
        _select_only(context, [])
        heightmap = read_gpx_and_create_heightmap(
            length=float(params.get("length", 50.0)),
            height=float(params.get("height", 10.0)),
            filepath=params.get("gpxPath") or None,
        )
        if heightmap is None:
            messages.append({"level": "ERROR", "text": _rpt("Choose a GPX file")})
            return False
        heightmap.location = (x, y, map_obj.location.z - 0.1)
        heightmap.rotation_euler.z = rotation
        heightmap.scale.x = -1
        # Into every tile's underside it reaches, like Text and SVG.
        targets = maps_covered_by(context, heightmap, maps, map_obj)
        if not targets:
            messages.append(_off_tiles_only_message())
            return False
        pieces = [heightmap] + [_duplicate(heightmap) for _ in targets[1:]]
        for target, piece in zip(targets, pieces):
            piece.location.z = target.location.z - 0.1
            context.scene.cursor.location = target.location.copy()
            operators_pe.finish_heightmap_placement(context, target, piece)
        return True

    # -- previews (nothing in the scene changes) ------------------------

    def preview(self, context, action, params, disabled=()):
        if action == "magnets":
            return self._preview_magnets(context, params, disabled)
        if action == "text":
            return self._preview_text(context, params)
        if action == "svg":
            return self._preview_svg(context, params)
        if action == "heightmap":
            return self._preview_heightmap(context, params)
        return None

    def _preview_magnets(self, context, params, disabled=()):
        from .operators import TP3D_OT_magnet_holes
        from .utils.magnet_layout import dovetail_footprints, magnet_layout
        from .utils.outline import get_bottom_outline, rotation_of

        tp3d = context.scene.tp3d
        diameter = float(params.get("diameter", tp3d.magnetDiameter))
        count = int(params.get("count", tp3d.magnetCount))
        margin = float(params.get("margin", tp3d.magnetMargin))
        maps, companions = self.enabled_objects(context, disabled)
        result = []
        for obj in maps:
            base = base_object(obj, companions)
            entry = {"map": obj.name, "target": base.name, "centers": [], "placed": 0,
                     "wanted": count, "already": bool(base.get("MagnetHoles"))}
            outline = get_bottom_outline(base)
            if outline is not None and not entry["already"]:
                shape = base.get("Shape")
                rotation = rotation_of(base, tp3d.shapeRotation)
                blocked = None
                if base.get("Dovetail") and "objSize" in base:
                    blocked = dovetail_footprints(base["objSize"], shape, rotation)
                centers = magnet_layout(outline, count, diameter, margin, blocked=blocked,
                                        shape=shape, rotation_deg=rotation)
                mw = base.matrix_world
                bottom_z = _world_bounds(base)[2]
                entry["centers"] = [list((mw @ Vector((cx, cy, 0.0))).xy) for cx, cy in centers]
                entry["placed"] = len(centers)
                entry["bottomZ"] = bottom_z
                local_bottom = min(c[2] for c in base.bound_box)
                available = TP3D_OT_magnet_holes._material_above(
                    None, base, centers, diameter / 2, local_bottom) if centers else None
                entry["available"] = available
            result.append(entry)
        return {"magnets": result}

    def _preview_text(self, context, params):
        body = str(params.get("text") or "").strip()
        if not body:
            return {"triangles": []}
        obj = _build_text_object(context, body, params.get("font") or "", float(params.get("size", 10.0)))
        try:
            return {"triangles": _flat_triangles(obj, context)}
        finally:
            curve = obj.data
            bpy.data.objects.remove(obj, do_unlink=True)
            if curve.users == 0:
                bpy.data.curves.remove(curve)

    def _preview_svg(self, context, params):
        from .utils.scene import importSVGtoMerge

        svg_path = params.get("svgPath") or ""
        if not svg_path:
            return {"triangles": []}
        maps = self.maps(context)
        active = context.view_layer.objects.active
        selected = list(context.selected_objects)
        cursor = context.scene.cursor.location.copy()
        context.scene.cursor.location = (0.0, 0.0, 0.0)
        svg = None
        try:
            svg = importSVGtoMerge(maps[0] if maps else None, svg_path)
            if svg is None:
                return {"triangles": [], "error": _rpt("The SVG file has no usable shapes.")}
            return {"triangles": _flat_triangles(svg, context)}
        finally:
            if svg is not None:
                _remove_object(svg)
            context.scene.cursor.location = cursor
            _select_only(context, [o for o in selected if _in_scene(context.scene, o)],
                         active if _in_scene(context.scene, active) else None)

    def _preview_heightmap(self, context, params):
        from .utils.io_gpx import gpx_height_profile

        points = gpx_height_profile(
            params.get("gpxPath") or None,
            float(params.get("length", 50.0)),
            float(params.get("height", 10.0)),
        )
        if points is None:
            return {"outline": [], "error": _rpt("No usable GPX track -- choose a GPX file.")}
        return {"outline": [list(p) for p in points]}


def _build_text_object(context, body, font_path, size):
    """A centred text object at the origin, like the Add Text popup makes."""
    curve = bpy.data.curves.new("Text", type="FONT")
    curve.body = body
    curve.align_x = "CENTER"
    curve.align_y = "CENTER"
    curve.size = max(0.1, size)
    if font_path:
        path = bpy.path.abspath(font_path)
        try:
            curve.font = bpy.data.fonts.load(path, check_existing=True)
        except (RuntimeError, OSError) as exc:
            print(f"[TP3D post-process] font load failed: {exc}")
    obj = bpy.data.objects.new("Text", curve)
    obj["type"] = "OTHER"
    context.collection.objects.link(obj)
    return obj


def _world_footprint(obj, context):
    """*obj*'s upward-facing triangles in world XY as one Shapely shape, or
    None if it has none."""
    from .utils import geometry2d as g2d

    flat = _flat_triangles(obj, context)
    if not flat:
        return None
    mw = obj.matrix_world
    pts = [mw @ Vector((flat[i], flat[i + 1], 0.0)) for i in range(0, len(flat), 2)]
    tris = []
    for i in range(0, len(pts) - 2, 3):
        tri = g2d.Polygon([(p.x, p.y) for p in pts[i:i + 3]])
        if tri.is_valid and tri.area > 1e-9:
            tris.append(tri)
    if not tris:
        return None
    return g2d.union_all(tris)


def _map_footprint_world(map_obj):
    """The map's footprint in world XY (Shapely), or its bounding box when
    it has no outline."""
    from shapely import affinity

    from .utils import geometry2d as g2d
    from .utils.outline import get_bottom_outline

    outline = get_bottom_outline(map_obj)
    if outline is None:
        minx, miny, _z0, maxx, maxy, _z1 = _world_bounds(map_obj)
        return g2d.box(minx, miny, maxx, maxy)
    m = map_obj.matrix_world
    return affinity.affine_transform(outline, [m[0][0], m[0][1], m[1][0], m[1][1], m[0][3], m[1][3]])


def maps_covered_by(context, obj, maps, primary):
    """The page maps *obj* (a positioned text/SVG/... shape) lies on: every
    map its footprint overlaps, *primary* (the map it was placed on) first.
    Just [primary] if the footprint can't be worked out. *primary* is left
    out when it isn't one of *maps* (a tile switched off on the page)."""
    footprint = _world_footprint(obj, context)
    if footprint is None or footprint.is_empty:
        return [primary] if primary in maps else []
    covered = [primary] if primary in maps else []
    for map_obj in maps:
        if map_obj is primary:
            continue
        try:
            overlap = footprint.intersection(_map_footprint_world(map_obj)).area
        except Exception as exc:  # noqa: BLE001 - a broken outline only skips that map
            print(f"[TP3D post-process] footprint test failed for {map_obj.name}: {exc}")
            continue
        if overlap > 0.01:  # mm²: more than a touching edge
            covered.append(map_obj)
    return covered


def _off_tiles_only_message():
    return {"level": "WARNING", "text": _rpt(
        "It only lies on tiles that are switched off. Click a tile in the 3D view to switch it back on.")}


def _duplicate(obj):
    copy = obj.copy()
    if obj.data is not None:
        copy.data = obj.data.copy()
    for collection in obj.users_collection:
        collection.objects.link(copy)
    return copy


def _flat_triangles(obj, context):
    """Upward-facing triangles of *obj* as a flat [x0, y0, x1, y1, ...]
    list in its local frame -- the 2D shape the page previews."""
    context.view_layer.update()
    evaluated = obj.evaluated_get(context.evaluated_depsgraph_get())
    mesh = evaluated.to_mesh()
    try:
        mesh.calc_loop_triangles()
        n = len(mesh.loop_triangles)
        if not n:
            return []
        tri_verts = np.empty(n * 3, dtype=np.int32)
        mesh.loop_triangles.foreach_get("vertices", tri_verts)
        normals = np.empty(n * 3, dtype=np.float32)
        mesh.loop_triangles.foreach_get("normal", normals)
        co = np.empty(len(mesh.vertices) * 3, dtype=np.float32)
        mesh.vertices.foreach_get("co", co)
        co = co.reshape(-1, 3)
        keep = normals.reshape(-1, 3)[:, 2] > 0.5
        if not keep.any():  # a flat fill without extrusion faces either way
            keep = np.abs(normals.reshape(-1, 3)[:, 2]) > 0.5
        tris = tri_verts.reshape(-1, 3)[keep]
        xy = co[tris.ravel(), :2]
        return [round(float(v), 3) for v in xy.ravel()]
    finally:
        evaluated.to_mesh_clear()


def settings_state(context) -> dict:
    """SETTINGS_STATE for the page: the scene's own post-process values, so
    the page starts where the sidebar is."""
    from .export import is_3mf_extension_installed
    from .utils.ui_state import build_online_access_state

    tp3d = context.scene.tp3d
    gpx = tp3d.get("file_path", "") or ""
    return {
        # has3mf / onlineAccess*: the Export button's 3MF install offer
        # (assets/threemf_promo.js).
        "has3mf": is_3mf_extension_installed(),
        **build_online_access_state(),
        "premium": bool(temp.PREMIUMVERSION),
        "mountain_treshold": tp3d.mountain_treshold,
        "mountain_color": list(tp3d.mountain_color),
        "mountain_noise": tp3d.mountain_noise,
        "mountain_noise_amplitude": tp3d.mountain_noise_amplitude,
        "mountain_noise_scale": tp3d.mountain_noise_scale,
        "color_height_SEM": tp3d.color_height_SEM,
        "color_height_MEM": tp3d.color_height_MEM,
        "toleranceElements": tp3d.toleranceElements,
        "elementShellThickness": tp3d.elementShellThickness,
        "cl_useRealMeters": tp3d.cl_useRealMeters,
        "cl_thickness": tp3d.cl_thickness,
        "cl_distance": tp3d.cl_distance,
        "cl_offset": tp3d.cl_offset,
        "magnetDiameter": tp3d.magnetDiameter,
        "magnetHeight": tp3d.magnetHeight,
        "magnetMargin": tp3d.magnetMargin,
        "magnetCount": tp3d.magnetCount,
        "bottomMarkCutout": tp3d.bottomMarkCutout,
        # Also what lets GET /font_file serve the scene's own text font.
        "textFont": tp3d.textFont,
        "gpxPath": bpy.path.abspath(gpx) if gpx else "",
        "addonVersion": const.ADDON_VERSION,
    }
